# kaliru plugin layer: mirror of Kalico klippy.extras.gcode_arcs (generated by tools/gen_mirror.py)
import _k

import math
ARC_PLANE_X_Y = 0
ARC_PLANE_X_Z = 1
ARC_PLANE_Y_Z = 2
X_AXIS = 0
Y_AXIS = 1
Z_AXIS = 2
E_AXIS = 3

class ArcSupport(_k.Object):
    __kaliru_mirror__ = True
    def __init__(self, config):
        _k.new(self, 1944, config)
    def cmd_G2(self, gcmd):
        return _k.call(self, 1945, gcmd)
    def cmd_G3(self, gcmd):
        return _k.call(self, 1946, gcmd)
    def cmd_G17(self, gcmd):
        return _k.call(self, 1947, gcmd)
    def cmd_G18(self, gcmd):
        return _k.call(self, 1948, gcmd)
    def cmd_G19(self, gcmd):
        return _k.call(self, 1949, gcmd)
    def _cmd_inner(self, gcmd, clockwise):
        return _k.call(self, 1950, gcmd, clockwise)
    def planArc(
        self,
        currentPos,
        targetPos,
        offset,
        clockwise,
        gcmd,
        absolut_extrude,
        alpha_axis,
        beta_axis,
        helical_axis,
    ):
        # todo: sometimes produces full circles

        # Radius vector from center to current location
        r_P = -offset[0]
        r_Q = -offset[1]

        # Determine angular travel
        center_P = currentPos[alpha_axis] - r_P
        center_Q = currentPos[beta_axis] - r_Q
        rt_Alpha = targetPos[alpha_axis] - center_P
        rt_Beta = targetPos[beta_axis] - center_Q
        angular_travel = math.atan2(
            r_P * rt_Beta - r_Q * rt_Alpha, r_P * rt_Alpha + r_Q * rt_Beta
        )
        if angular_travel < 0.0:
            angular_travel += 2.0 * math.pi
        if clockwise:
            angular_travel -= 2.0 * math.pi

        if (
            angular_travel == 0.0
            and currentPos[alpha_axis] == targetPos[alpha_axis]
            and currentPos[beta_axis] == targetPos[beta_axis]
        ):
            # Make a circle if the angular rotation is 0 and the
            # target is current position
            angular_travel = 2.0 * math.pi

        # Determine number of segments
        linear_travel = targetPos[helical_axis] - currentPos[helical_axis]
        radius = math.hypot(r_P, r_Q)
        flat_mm = radius * angular_travel
        if linear_travel:
            mm_of_travel = math.hypot(flat_mm, linear_travel)
        else:
            mm_of_travel = math.fabs(flat_mm)
        segments = max(1.0, math.floor(mm_of_travel / self.mm_per_arc_segment))

        # Generate coordinates
        theta_per_segment = angular_travel / segments
        linear_per_segment = linear_travel / segments

        asE = gcmd.get_float("E", None)
        asF = gcmd.get_float("F", None)

        e_per_move = e_base = 0.0
        if asE is not None:
            if absolut_extrude:
                e_base = currentPos[3]
            e_per_move = (asE - e_base) / segments

        for i in range(1, int(segments) + 1):
            dist_Helical = i * linear_per_segment
            c_theta = i * theta_per_segment
            cos_Ti = math.cos(c_theta)
            sin_Ti = math.sin(c_theta)
            r_P = -offset[0] * cos_Ti + offset[1] * sin_Ti
            r_Q = -offset[0] * sin_Ti - offset[1] * cos_Ti

            c = [None, None, None]
            c[alpha_axis] = center_P + r_P
            c[beta_axis] = center_Q + r_Q
            c[helical_axis] = currentPos[helical_axis] + dist_Helical

            if i == segments:
                c = targetPos
            # Convert coords into G1 commands
            g1_params = {"X": c[0], "Y": c[1], "Z": c[2]}
            if e_per_move:
                g1_params["E"] = e_base + e_per_move
                if absolut_extrude:
                    e_base += e_per_move
            if asF is not None:
                g1_params["F"] = asF
            g1_gcmd = self.gcode.create_gcode_command("G1", "G1", g1_params)
            self.gcode_move.cmd_G1(g1_gcmd)
    gcode = _k.Attr(1952, 'gcode')
    gcode_move = _k.Attr(1953, 'gcode_move')
    mm_per_arc_segment = _k.Attr(1954, 'mm_per_arc_segment')
    plane = _k.Attr(1955, 'plane')
    printer = _k.Attr(1956, 'printer')

def load_config(config):
    return _k.fcall(1957, config)


__getattr__ = _k.module_getattr(__name__)
